// AfterQueryHook is called after GameServer is retrieved from the database
func (o *GameServer) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = GameServers.AfterSelectHooks.RunHooks(ctx, exec, GameServerSlice{o})
	case bob.QueryTypeInsert:
		ctx, err = GameServers.AfterInsertHooks.RunHooks(ctx, exec, GameServerSlice{o})
	case bob.QueryTypeUpdate:
		ctx, err = GameServers.AfterUpdateHooks.RunHooks(ctx, exec, GameServerSlice{o})
	case bob.QueryTypeDelete:
		ctx, err = GameServers.AfterDeleteHooks.RunHooks(ctx, exec, GameServerSlice{o})
	}

	return err
}

